#!/usr/bin/env bash
# Create the travel "trip form" WhatsApp Flow in Meta and put its ID into .env (TRAVEL_TRIP_FLOW_ID).
# The form is n8n/whatsapp-flows/travel_trip.json (generated by plan/build_travel_workflows.py).
#
#   scripts/create-travel-flow.sh            create + upload; sent in draft mode (fine for testing)
#   scripts/create-travel-flow.sh --publish  also publish it (needed for real users; a published
#                                            flow can't be changed: run again to make a new one)
# Needs BOT_WABA_ID (Meta → app → WhatsApp → API Setup → "WhatsApp Business Account ID") and a valid
# BOT_WHATSAPP_TOKEN with whatsapp_business_management.
set -euo pipefail
cd "$(dirname "$0")/.."
set -a; . ./.env; set +a
: "${BOT_WABA_ID:?set BOT_WABA_ID in .env (Meta → app → WhatsApp → API Setup → WhatsApp Business Account ID)}"
G=https://graph.facebook.com/v21.0
AUTH="Authorization: Bearer ${BOT_WHATSAPP_TOKEN}"
field() { python3 -c "import json,sys; d=json.load(sys.stdin); print($1)"; }
setenv() {  # setenv KEY VALUE: replace or append in .env
  if grep -q "^$1=" .env; then sed -i "s#^$1=.*#$1=$2#" .env; else echo "$1=$2" >> .env; fi
}

r=$(curl -s -H "$AUTH" -X POST "$G/$BOT_WABA_ID/flows" \
  -F "name=tori_travel_trip_$(date +%Y%m%d%H%M%S)" -F 'categories=["OTHER"]')
flow_id=$(echo "$r" | field "d.get('id', '')")
[ -n "$flow_id" ] || { echo "could not create the flow: $r" >&2; exit 1; }
echo "created flow $flow_id"

r=$(curl -s -H "$AUTH" -X POST "$G/$flow_id/assets" \
  -F "file=@n8n/whatsapp-flows/travel_trip.json;type=application/json" -F name=flow.json -F asset_type=FLOW_JSON)
errors=$(echo "$r" | field "d.get('validation_errors') or (d.get('error') or '')")
[ -z "$errors" ] || { echo "Meta rejected the form: $errors" >&2; exit 1; }
echo "form uploaded"

mode=draft
if [ "${1:-}" = --publish ]; then
  r=$(curl -s -H "$AUTH" -X POST "$G/$flow_id/publish")
  case "$r" in *'"success":true'*) mode=published; echo "published" ;; *) echo "could not publish: $r" >&2; exit 1 ;; esac
fi

setenv TRAVEL_TRIP_FLOW_ID "$flow_id"
setenv TRAVEL_TRIP_FLOW_MODE "$mode"
echo
echo "TRAVEL_TRIP_FLOW_ID=$flow_id and TRAVEL_TRIP_FLOW_MODE=$mode written to .env."
echo "Apply it: docker compose up -d   (then ask the bot for a cab buddy without giving details)"
